'use strict';

// MODULES //

var tape = require( 'tape' );
var ctor = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof ctor, 'function', 'main export is a function' );
	t.end();
});

tape( 'an instance throws an error if provided an invalid `lineWidth` value', function test( t ) {
	var values;
	var i;

	values = [
		'5',
		null,
		void 0,
		true,
		false,
		{},
		[ 'beep' ],
		[ 2, '4' ],
		function noop() {}
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			var chart = ctor();
			chart.lineWidth = value;
		};
	}
});

tape( 'an instance supports setting and getting the property value', function test( t ) {
	var chart;

	chart = ctor({
		'lineWidth': [ 2, 4 ]
	});
	t.deepEqual( chart.lineWidth, [ 2, 4 ], 'returns expected value' );

	chart.lineWidth = [ 1 ];
	t.deepEqual( chart.lineWidth, [ 1 ], 'returns expected value' );

	t.end();
});

tape( 'an instance coerces a number value to an array containing a single value', function test( t ) {
	var chart;

	chart = ctor({
		'lineWidth': 4
	});
	t.deepEqual( chart.lineWidth, [ 4 ], 'returns expected value' );

	chart.lineWidth = 1;
	t.deepEqual( chart.lineWidth, [ 1 ], 'returns expected value' );

	t.end();
});

tape( 'an instance performs a defensive copy of a provided array', function test( t ) {
	var chart;
	var arr;

	arr = [ 2, 4 ];
	chart = ctor({
		'lineWidth': arr
	});
	t.notEqual( chart.lineWidth, arr, 'returns a copy' );
	t.deepEqual( chart.lineWidth, arr, 'returns expected value' );

	arr.push( 6 );
	t.deepEqual( chart.lineWidth, [ 2, 4 ], 'returns expected value' );

	t.end();
});

tape( 'setting the property updates the line width scale range', function test( t ) {
	var chart = ctor();

	chart.lineWidth = [ 2, 4 ];
	t.deepEqual( chart.lineWidthScale.range, [ 2, 4 ], 'returns expected value' );

	chart.lineWidth = 1;
	t.deepEqual( chart.lineWidthScale.range, [ 1 ], 'returns expected value' );

	t.end();
});

tape( 'setting the `lineWidth` property to a new value triggers a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'lineWidth': [ 2 ]
	});

	chart.on( 'change', onChange );
	chart.lineWidth = [ 4 ];

	function onChange() {
		t.ok( true, 'triggers event' );
		t.end();
	}
});

tape( 'setting the `lineWidth` property to its current value does not trigger a `change` event', function test( t ) {
	var chart;

	chart = ctor({
		'lineWidth': [ 4 ]
	});

	chart.on( 'change', onChange );
	chart.lineWidth = [ 4 ];
	chart.lineWidth = 4;

	t.ok( true, 'does not trigger event' );
	t.end();

	function onChange() {
		t.ok( false, 'should not trigger event' );
	}
});
